import sys
import os
import hashlib
import subprocess
from typing import List, Tuple

def compute_digest(file_path: str, key: bytes) -> str:
    with open(file_path, 'rb') as f:
        file_data = f.read()
    digest = hashlib.sha256(key + file_data).digest()
    return digest.hex()

def mode1():
    key = open('manifest.key', 'rb').read().strip()
    if len(key) != 32:
        sys.exit(1)
    cmd = sys.stdin.readline().strip()
    result = subprocess.run(cmd, shell=True, capture_output=True, text=True)
    if result.returncode != 0:
        sys.exit(1)
    file_paths = [line.strip() for line in result.stdout.splitlines() if line.strip()]
    digests = []
    for path in file_paths:
        if not os.path.exists(path):
            sys.exit(1)
        digest = compute_digest(path, key)
        digests.append((digest, path))
    with open('manifest.txt', 'w') as f:
        for digest, path in digests:
            f.write(f"{digest} {path}\n")

def mode2():
    key = open('manifest.key', 'rb').read().strip()
    if len(key) != 32:
        sys.exit(1)
    with open('manifest.txt', 'r') as f:
        lines = f.readlines()
    changed_files = []
    for line in lines:
        parts = line.strip().split()
        if len(parts) != 2:
            sys.exit(1)
        digest, path = parts
        try:
            with open(path, 'rb') as f:
                file_data = f.read()
            computed_digest = hashlib.sha256(key + file_data).digest().hex()
            if computed_digest != digest:
                changed_files.append(f"{path} changed")
        except IOError:
            changed_files.append(f"{path} missing")
    for line in changed_files:
        print(line)
    sys.exit(0 if not changed_files else 1)

if __name__ == "__main__":
    if len(sys.argv) == 1:
        mode1()
    elif sys.argv[1] == 'check':
        mode2()
    else:
        sys.exit(1)

import os
import sys
import hashlib

def compute_digest(file_path, key):
    hasher = hashlib.sha256()
    hasher.update(key)
    try:
        with open(file_path, 'rb') as f:
            hasher.update(f.read())
    except FileNotFoundError:
        return None
    return hasher.hexdigest()

def mode_1():
    command = input().strip()
    output = os.popen(command).readlines()
    output = [line.strip() for line in output if line.strip()]

    key_path = 'manifest.key'
    with open(key_path, 'rb') as key_file:
        key = key_file.read()

    with open('manifest.txt', 'w') as manifest_file:
        for file_path in output:
            digest = compute_digest(file_path, key)
            if digest:
                manifest_file.write(f'{digest} {file_path}\n')

def mode_2():
    if len(sys.argv) != 2 or sys.argv[1] != 'check':
        return

    key_path = 'manifest.key'
    with open(key_path, 'rb') as key_file:
        key = key_file.read()

    with open('manifest.txt', 'r') as manifest_file:
        lines = manifest_file.readlines()

    status_lines = []
    for line in lines:
        digest, file_path = line.strip().split(' ', 1)
        current_digest = compute_digest(file_path, key)
        if current_digest is None:
            status_lines.append(f'{file_path} missing')
        elif current_digest != digest:
            status_lines.append(f'{file_path} changed')

    if status_lines:
        print('\n'.join(status_lines))
        sys.exit(1)
    else:
        sys.exit(0)

if __name__ == '__main__':
    if len(sys.argv) == 1:
        mode_1()
    elif len(sys.argv) == 2:
        mode_2()
